using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    // Register a named HttpClient that will be injected into WeatherTools.
    // IHttpClientFactory manages handler lifetimes and pooling automatically.
    .AddHttpClient<WeatherTools>(client =>
    {
        client.DefaultRequestHeaders.Add("User-Agent", "McpWeatherServer/1.0");
    });

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

