26.     [McpServerTool(Name = "get_forecast"),
27.      Description("Get a 7-day weather forecast for a location. " +
28.                  "Returns daily high/low temperatures in the requested unit.")]
29.     public async Task<string> GetForecastAsync(
30.         [Description("Latitude of the location (e.g. 47.6062)")] double latitude,
31.         [Description("Longitude of the location (e.g. -122.3321)")] double longitude,
32.         [Description("Temperature unit: 'celsius' or 'fahrenheit'")] string unit = "celsius")
33.     {
34.         var tempUnit = unit.Equals("fahrenheit", StringComparison.OrdinalIgnoreCase)
35.             ? "fahrenheit"
36.             : "celsius";
37. 
38.         var url = $"https://api.open-meteo.com/v1/forecast" +
39.                   $"?latitude={latitude}&longitude={longitude}" +
40.                   $"&daily=temperature_2m_max,temperature_2m_min" +
41.                   $"&temperature_unit={tempUnit}&timezone=auto";
42. 
43.         var response = await _http.GetFromJsonAsync<ForecastResponse>(url);
44.         if (response?.Daily is null)
45.             return "No forecast data available.";
46. 
47.         var lines = new List<string> { $"7-day forecast ({tempUnit}):" };
48.         for (var i = 0; i < response.Daily.Time.Count; i++)
49.         {
50.             lines.Add($"  {response.Daily.Time[i]}: " +
51.                        $"High {response.Daily.TemperatureMax[i]}° / " +
52.                        $"Low {response.Daily.TemperatureMin[i]}°");
53.         }
54. 
55.         return string.Join('\n', lines);
56.     }
57. 
