59.      Description("Get current weather conditions for a location.")]
60.     public async Task<string> GetCurrentWeatherAsync(
61.         [Description("Latitude of the location")] double latitude,
62.         [Description("Longitude of the location")] double longitude)
63.     {
64.         var url = $"https://api.open-meteo.com/v1/forecast" +
65.                   $"?latitude={latitude}&longitude={longitude}" +
66.                   $"&current=temperature_2m,wind_speed_10m,relative_humidity_2m" +
67.                   $"&timezone=auto";
68. 
69.         var response = await _http.GetFromJsonAsync<CurrentResponse>(url);
70.         if (response?.Current is null)
71.             return "No current weather data available.";
72. 
73.         return $"Current weather at ({latitude}, {longitude}):\n" +
74.                $"  Temperature: {response.Current.Temperature}°C\n" +
75.                $"  Wind speed:  {response.Current.WindSpeed} km/h\n" +
76.                $"  Humidity:    {response.Current.Humidity}%";
77.     }
78. 
