 using System.ComponentModel;
 using System.Net.Http.Json;
 using System.Text.Json.Serialization;
 using ModelContextProtocol.Server;

 namespace McpServer;

 /// <summary>
 /// MCP tools that wrap the Open-Meteo weather REST API.
 /// The MCP SDK discovers methods decorated with [McpServerTool] and registers
 /// them automatically. Constructor parameters are resolved from DI.
 /// </summary>
 [McpServerToolType]
 public sealed class WeatherTools
 {
     private readonly HttpClient _http;

     // HttpClient is injected by the DI container via IHttpClientFactory's
     // named-client support. The MCP SDK instantiates tool classes from DI
     // each time a tool is called, so constructor injection works naturally.
     public WeatherTools(HttpClient http)
     {
         _http = http;
     }

     [McpServerTool(Name = "get_forecast"),
      Description("Get a 7-day weather forecast for a location. " +
                  "Returns daily high/low temperatures in the requested unit.")]
     public async Task<string> GetForecastAsync(
         [Description("Latitude of the location (e.g. 47.6062)")] double latitude,
         [Description("Longitude of the location (e.g. -122.3321)")] double longitude,
         [Description("Temperature unit: 'celsius' or 'fahrenheit'")] string unit = "celsius")
     {
         var tempUnit = unit.Equals("fahrenheit", StringComparison.OrdinalIgnoreCase)
             ? "fahrenheit"
             : "celsius";

         var url = $"https://api.open-meteo.com/v1/forecast" +
                   $"?latitude={latitude}&longitude={longitude}" +
                   $"&daily=temperature_2m_max,temperature_2m_min" +
                   $"&temperature_unit={tempUnit}&timezone=auto";

         var response = await _http.GetFromJsonAsync<ForecastResponse>(url);
         if (response?.Daily is null)
             return "No forecast data available.";

         var lines = new List<string> { $"7-day forecast ({tempUnit}):" };
         for (var i = 0; i < response.Daily.Time.Count; i++)
         {
             lines.Add($"  {response.Daily.Time[i]}: " +
                        $"High {response.Daily.TemperatureMax[i]}° / " +
                        $"Low {response.Daily.TemperatureMin[i]}°");
         }

         return string.Join('\n', lines);
     }

     [McpServerTool(Name = "get_current_weather"),
      Description("Get current weather conditions for a location.")]
     public async Task<string> GetCurrentWeatherAsync(
         [Description("Latitude of the location")] double latitude,
         [Description("Longitude of the location")] double longitude)
     {
         var url = $"https://api.open-meteo.com/v1/forecast" +
                   $"?latitude={latitude}&longitude={longitude}" +
                   $"&current=temperature_2m,wind_speed_10m,relative_humidity_2m" +
                   $"&timezone=auto";

         var response = await _http.GetFromJsonAsync<CurrentResponse>(url);
         if (response?.Current is null)
             return "No current weather data available.";

         return $"Current weather at ({latitude}, {longitude}):\n" +
                $"  Temperature: {response.Current.Temperature}°C\n" +
                $"  Wind speed:  {response.Current.WindSpeed} km/h\n" +
                $"  Humidity:    {response.Current.Humidity}%";
     }

     // --- Response DTOs ---

     private sealed class ForecastResponse
     {
         [JsonPropertyName("daily")]
         public DailyData? Daily { get; set; }
     }

     private sealed class DailyData
     {
         [JsonPropertyName("time")]
         public List<string> Time { get; set; } = [];

         [JsonPropertyName("temperature_2m_max")]
         public List<double> TemperatureMax { get; set; } = [];

         [JsonPropertyName("temperature_2m_min")]
         public List<double> TemperatureMin { get; set; } = [];
     }

     private sealed class CurrentResponse
     {
         [JsonPropertyName("current")]
         public CurrentData? Current { get; set; }
     }

     private sealed class CurrentData
     {
         [JsonPropertyName("temperature_2m")]
         public double Temperature { get; set; }

         [JsonPropertyName("wind_speed_10m")]
         public double WindSpeed { get; set; }

         [JsonPropertyName("relative_humidity_2m")]
         public int Humidity { get; set; }
     }
 }

